begin;
create extension if not exists pgtap with schema extensions;
select plan(44);
insert into public.colleges(code,name) values('ATT-TEST','Attendance Test College');
insert into public.programs(college_id,name) select id,'Attendance Test Program' from public.colleges where code='ATT-TEST';
insert into public.event_categories(name,slug) values('Attendance Test','attendance-test');
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,is_anonymous,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','att-'||n||'@test.local',now(),'{}','{"first_name":"Attendance","last_name":"Test"}',false,now(),now() from generate_series(1,6)n;
update public.profiles set student_id='ATT-'||right(id::text,4),college_id=(select id from public.colleges where code='ATT-TEST'),program_id=(select id from public.programs where name='Attendance Test Program'),year_level=1,avatar_path=id::text||'/photo.png',privacy_consented_at=now(),privacy_notice_version='2026-10-draft' where id::text like 'd1000000-%' and id<>'d1000000-0000-4000-8000-000000000006';
update public.profiles set organizer_status='active',organizer_since=now() where id='d1000000-0000-4000-8000-000000000001';
insert into public.events(id,organizer_id,title,description,venue,category_id,starts_at,ends_at,registration_opens_at,registration_closes_at,status,attendance_policy,allow_onsite_registration)
values('de000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000001','Attendance Test Event',repeat('description ',3),'University Hall',(select id from public.event_categories where slug='attendance-test'),now()-interval '1 hour',now()+interval '1 hour',now()-interval '1 day',now()-interval '2 hours','published','time_in_and_out',true);
insert into public.event_registrations(id,event_id,user_id,status) select ('da000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'de000000-0000-4000-8000-000000000001',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'pending'::public.registration_status else 'approved'::public.registration_status end from generate_series(2,4)n;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
set local role authenticated;
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000001','time_in'),'ok','owner opens time-in');
select is(jsonb_array_length(public.get_attendance_qr('de000000-0000-4000-8000-000000000001')->'tokens'),3,'current plus two windows prefetched');
select set_config('test.token',public.get_attendance_qr('de000000-0000-4000-8000-000000000001')->'tokens'->0->>'token',true);
select set_config('test.future',public.get_attendance_qr('de000000-0000-4000-8000-000000000001')->'tokens'->1->>'token',true);
reset role;
select set_config('test.previous',private.attendance_token((select id from public.attendance_sessions where event_id='de000000-0000-4000-8000-000000000001' and status='open'),floor(extract(epoch from now())/30)::integer-1),true);
select set_config('test.expired',private.attendance_token((select id from public.attendance_sessions where event_id='de000000-0000-4000-8000-000000000001' and status='open'),floor(extract(epoch from now())/30)::integer-2),true);
set local role authenticated;
select is(length(current_setting('test.token')),48,'36-byte compact token');
select is(public.set_attendance_settings('de000000-0000-4000-8000-000000000001','time_in_only',60,true),'attendance_locked','policy locked after session');
select throws_ok($$select * from public.attendance_session_secrets$$,'42501',null,'secrets cannot be read');
select throws_ok($$select * from public.attendance_device_signals$$,'42501',null,'device evidence cannot be read');
select throws_ok($$insert into public.attendance_records(registration_id,event_id,user_id,time_in_method) values('da000000-0000-4000-8000-000000000002','de000000-0000-4000-8000-000000000001',auth.uid(),'manual')$$,'42501',null,'direct attendance inserts denied');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":false}',true);
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000001','time_in'),'not_permitted','participant cannot manage attendance');
select ok(public.get_attendance_feed('de000000-0000-4000-8000-000000000001') is null,'participant cannot read public display feed');
select is(public.submit_attendance_scan('invalid','device-test-123456')->>'code','invalid_qr','static registration QR rejected');
select is(public.submit_attendance_scan(current_setting('test.future'),'device-test-123456')->>'code','expired_qr','future token rejected');
select is(public.submit_attendance_scan(current_setting('test.expired'),'device-test-123456')->>'code','expired_qr','old token rejected');
select is(public.submit_attendance_scan(left(current_setting('test.token'),47)||case when right(current_setting('test.token'),1)='A' then 'B' else 'A' end,'device-test-123456')->>'code','invalid_qr','tampered MAC rejected');
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456','de000000-0000-4000-8000-000000000009')->>'code','wrong_event','event mismatch rejected');
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','timed_in','approved participant timed in');
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','already_timed_in','duplicate scan idempotent');
select is(public.submit_attendance_scan(current_setting('test.previous'),'device-test-123456')->>'code','already_timed_in','previous window remains accepted');
select is((select count(*)::int from public.attendance_records),1,'participant only reads own attendance');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000004","role":"authenticated","is_anonymous":false}',true);
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','registration_not_approved','pending participant denied');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000006","role":"authenticated","is_anonymous":false}',true);
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','profile_incomplete','incomplete participant denied');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000005","role":"authenticated","is_anonymous":false}',true);
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','not_registered','unregistered participant denied');
select is(public.register_for_event('de000000-0000-4000-8000-000000000001'),'registration_closed','attendance permanently closes registration, including onsite');
select is((select count(*)::int from public.event_registrations where user_id=auth.uid()),0,'closed registration creates no onsite record');
-- Keep the existing time-out-without-time-in regression independent of registration creation.
reset role;
insert into public.event_registrations(event_id,user_id,status) values('de000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','approved');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","is_anonymous":false}',true);
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','timed_in','second approved user times in');
select is((select flag from public.attendance_records where user_id=auth.uid()),'shared_device','shared device flagged');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
select is((select count(*)::int from public.attendance_records where flag='shared_device'),2,'all affected records flagged');
select ok(not ((public.get_attendance_feed('de000000-0000-4000-8000-000000000001')->'records'->0)?|array['email','student_id','reason','program_id']),'display whitelist omits private fields');
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000001','time_out'),'ok','time-out replaces time-in');
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000001','time_in'),'time_out_started','late time-in denied');
select set_config('test.out',public.get_attendance_qr('de000000-0000-4000-8000-000000000001')->'tokens'->0->>'token',true);
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":false}',true);
select is(public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')->>'code','attendance_closed','closed-session token invalidated');
select is(public.submit_attendance_scan(current_setting('test.out'),'device-test-123456')->>'code','timed_out','valid timeout');
select is(public.submit_attendance_scan(current_setting('test.out'),'device-test-123456')->>'code','already_timed_out','duplicate timeout idempotent');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000005","role":"authenticated","is_anonymous":false}',true);
select is(public.submit_attendance_scan(current_setting('test.out'),'other-device-123456')->>'code','time_in_required','timeout requires time-in');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
select is(public.correct_attendance('da000000-0000-4000-8000-000000000002','clear_flag',''),'reason_required','correction requires note');
select is(public.correct_attendance('da000000-0000-4000-8000-000000000002','clear_flag','Verified participant at venue'),'ok','owner resolves flag');
select is(public.correct_attendance('da000000-0000-4000-8000-000000000003','revoke_flag','Proxy attendance confirmed'),'ok','owner revokes flagged attendance');
reset role;
select throws_ok($$update public.events set starts_at=starts_at-interval '1 hour' where id='de000000-0000-4000-8000-000000000001'$$,'23514',null,'schedule locked after attendance starts');
insert into public.events(id,organizer_id,title,description,venue,category_id,starts_at,ends_at,registration_opens_at,registration_closes_at,status)
select 'de000000-0000-4000-8000-000000000002',organizer_id,'Future Attendance Event',description,venue,category_id,now()+interval '2 days',now()+interval '2 days 1 hour',registration_opens_at,registration_closes_at,'published' from public.events where id='de000000-0000-4000-8000-000000000001';
set local role authenticated;
-- Since 20261022090000 the Organizer opens attendance manually, regardless of the scheduled time.
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000002','time_in'),'ok','organizer opens attendance before the scheduled start');
reset role;
update public.profiles set organizer_status='suspended' where id='d1000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.attendance_sessions where event_id='de000000-0000-4000-8000-000000000001' and status='open'),0,'suspension closes open sessions');
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000001','time_out'),'not_permitted','suspended organizer cannot reopen');
reset role;
update public.profiles set organizer_status='active' where id='d1000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.open_attendance_session('de000000-0000-4000-8000-000000000001','time_out'),'ok','reinstated owner reopens timeout');
select set_config('test.out',public.get_attendance_qr('de000000-0000-4000-8000-000000000001')->'tokens'->0->>'token',true);
select is(public.complete_event('de000000-0000-4000-8000-000000000001'),'ok','owner completes event');
select is(public.submit_attendance_scan(current_setting('test.out'),'other-device-123456')->>'code','attendance_closed','completion invalidates QR');
set local role anon;
select throws_ok($$select public.submit_attendance_scan(current_setting('test.token'),'device-test-123456')$$,'42501',null,'anonymous cannot submit scans');
select * from finish();
rollback;
